import{_ as a,o as s,c as o,am as n}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"什么是 Docker","description":"","frontmatter":{"title":"什么是 Docker","excerpt":"Dokcer入门_基础概念","date":"2023-11-17 12:10:27","updated":"2023-11-17 12:10:27"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/Docker 基础/什么是 Docker.md","filePath":"部署&工具/Java 知识体系-容器部署/Docker 基础/什么是 Docker.md","lastUpdated":null}'),t={name:"部署&工具/Java 知识体系-容器部署/Docker 基础/什么是 Docker.md"};function r(p,e,c,l,i,d){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h3 id="_1、什么是-docker" tabindex="-1">1、什么是 Docker <a class="header-anchor" href="#_1、什么是-docker" aria-label="Permalink to &quot;1、什么是 Docker&quot;">​</a></h3><blockquote><p>理解虚拟化技术</p></blockquote><p>人们为了提高系统及硬件资源的利用率而引入了<strong>虚拟化技术</strong>。虚拟化是一种<strong>资源管理技术</strong>，它可以各种实体资源抽像后再分隔，从而打破实体结构的限制，最大程度的提高资源的利用率。</p><p>虚拟化的目的是为了在同一个主机上运行多个系统或应用，从而提高系统资源的利用率，并带来降低成本、方便管理和容错容灾等好处。</p><p>从实现形式来分，虚拟化技术可分为基于硬件的虚拟化和基于软件的虚拟化。</p><blockquote><p>基于软件的虚拟化</p></blockquote><p>软件虚拟化是利用软件技术，在现有的物理平台上实现对物理平台访问的截获和模拟。</p><p>对软件虚拟化进行细分，又可以分为以下几类：</p><ul><li>完全虚拟化</li><li>硬件辅助虚拟化</li><li>部分虚拟化</li><li>平行虚拟化</li><li>操作系统层虚拟化</li></ul><p>Docker容器技术就是属于操作系统层虚拟化的范畴。</p><p>虚拟化是通过软件的方式模拟实体服务器，其初衷是为了解决“一种应用占用一台服务器”模式所带来的服务器数量剧增的问题，从而降低数据中心复杂度，简化管理难度。</p><blockquote><p>虚拟机和Docker</p></blockquote><p>容器虚拟化的是操作系统而不是硬件，容器之间是共享同一套操作系统资源。</p><p>虚拟机技术是虚拟出一套硬件后，在其上运行一个完整操作系统。因此容器的隔离级别会稍低一些。</p><blockquote><p>虚拟机和 Docker 的对比 <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311171252304.png" alt="image.png"></p></blockquote><blockquote><p>图解物理机,虚拟机与容器</p></blockquote><p>物理机</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311171456074.png" alt="image.png"></p><p>虚拟机</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311171456887.png" alt="image.png"> 容器</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311171457700.png" alt="image.png"></p><p>虚拟机和Docker容器各自有自己的应用场景，<strong>虚拟机更擅长于彻底隔离整个运行环境</strong>。例如，云服务提供商通常采用虚拟机技术隔离不同的用户。</p><p>而 <strong>Docker 通常用于隔离不同的应用</strong> ，例如前端，后端以及数据库。</p><h3 id="_2、docker-基本概念" tabindex="-1">2、Docker 基本概念 <a class="header-anchor" href="#_2、docker-基本概念" aria-label="Permalink to &quot;2、Docker 基本概念&quot;">​</a></h3><p>Docker 包括三个基本概念:</p><ul><li><strong>镜像（Image）</strong>：Docker 镜像（Image），就相当于是一个 root 文件系统。比如官方镜像 ubuntu:16.04 就包含了完整的一套 Ubuntu16.04 最小系统的 root 文件系统。</li><li><strong>容器（Container）</strong>：镜像（Image）和容器（Container）的关系，就像是面向对象程序设计中的类和实例一样，<strong>镜像是静态的定义，容器是镜像运行时的实体</strong>。容器可以被创建、启动、停止、删除、暂停等。</li><li><strong>仓库（Repository）</strong>：仓库可看成一个代码控制中心，用来保存镜像。</li></ul><blockquote><p><strong>Docker Registry 公开服务和私有 Docker Registry</strong></p></blockquote><p><strong>Docker Registry 公开服务</strong> 是开放给用户使用、允许用户管理镜像的 Registry 服务。一般这类公开服务允许用户免费上传、下载公开的镜像，并可能提供收费服务供用户管理私有镜像。</p><p>最常使用的 Registry 公开服务是官方的 <strong>Docker Hub</strong> ，这也是默认的 Registry，并拥有大量的高质量的官方镜像，网址为：<a href="https://hub.docker.com/" title="https://hub.docker.com/" target="_blank" rel="noreferrer">https://hub.docker.com/open in new window</a> 。官方是这样介绍 Docker Hub 的：</p><blockquote><p>Docker Hub 是 Docker 官方提供的一项服务，用于与您的团队查找和共享容器镜像。</p></blockquote><p>比如我们想要搜索自己想要的镜像：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311171534204.png" alt="image.png"></p><p>在 Docker Hub 的搜索结果中，有几项关键的信息有助于我们选择合适的镜像：</p><ul><li><strong>OFFICIAL Image</strong>：代表镜像为 Docker 官方提供和维护，相对来说稳定性和安全性较高。</li><li><strong>Stars</strong>：和点赞差不多的意思，类似 GitHub 的 Star。</li><li><strong>Downloads</strong>：代表镜像被拉取的次数，基本上能够表示镜像被使用的频度。</li></ul><p>除了直接通过 Docker Hub 网站搜索镜像这种方式外，我们还可以通过 <code>docker search</code> 这个命令搜索 Docker Hub 中的镜像，搜索的结果是一致的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>➜  ~ docker search mysql</span></span>
<span class="line"><span>NAME                              DESCRIPTION                                     STARS               OFFICIAL            AUTOMATED</span></span>
<span class="line"><span>mysql                             MySQL is a widely used, open-source relation…   8763                [OK]</span></span>
<span class="line"><span>mariadb                           MariaDB is a community-developed fork of MyS…   3073                [OK]</span></span>
<span class="line"><span>mysql/mysql-server                Optimized MySQL Server Docker images. Create…   650                                     [OK]</span></span></code></pre></div><p>在国内访问<strong>Docker Hub</strong> 可能会比较慢国内也有一些云服务商提供类似于 Docker Hub 的公开服务。比如 <a href="https://www.aliyun.com/product/containerservice?utm_content=se_1292836" title="阿里云镜像库" target="_blank" rel="noreferrer">阿里云镜像库</a>。</p><p>除了使用公开服务外，用户还可以在 <strong>本地搭建私有 Docker Registry</strong> 。</p><p>Docker 官方提供了 Docker Registry 镜像，可以直接使用做为私有 Registry 服务。开源的 Docker Registry 镜像只提供了 Docker Registry API 的服务端实现，足以支持 docker 命令，不影响使用。但不包含图形界面，以及镜像维护、用户管理、访问控制等高级功能。</p><h3 id="_3、基本命令" tabindex="-1">3、基本命令 <a class="header-anchor" href="#_3、基本命令" aria-label="Permalink to &quot;3、基本命令&quot;">​</a></h3><h4 id="基本命令" tabindex="-1">基本命令 <a class="header-anchor" href="#基本命令" aria-label="Permalink to &quot;基本命令&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker version # 查看docker版本</span></span>
<span class="line"><span>docker images # 查看所有已下载镜像，等价于：docker image ls 命令</span></span>
<span class="line"><span>docker container ls # 查看所有容器</span></span>
<span class="line"><span>docker ps #查看正在运行的容器</span></span>
<span class="line"><span>docker image prune # 清理临时的、没有被使用的镜像文件。-a, --all: 删除所有没有用的镜像，而不仅仅是临时文件；</span></span></code></pre></div><h4 id="拉取镜像" tabindex="-1">拉取镜像 <a class="header-anchor" href="#拉取镜像" aria-label="Permalink to &quot;拉取镜像&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker search mysql # 查看mysql相关镜像</span></span>
<span class="line"><span>docker pull mysql:5.7 # 拉取mysql镜像</span></span>
<span class="line"><span>docker image ls # 查看所有已下载镜像</span></span></code></pre></div><h4 id="删除镜像" tabindex="-1">删除镜像 <a class="header-anchor" href="#删除镜像" aria-label="Permalink to &quot;删除镜像&quot;">​</a></h4><p>比如我们要删除我们下载的 mysql 镜像。</p><p>通过 <code>docker rmi [image]</code> （等价于<code>docker image rm [image]</code>）删除镜像之前首先要确保这个镜像没有被容器引用（可以通过标签名称或者镜像 ID 删除）。</p><p>通过我们前面讲的<code>docker ps</code>命令即可查看。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>➜  ~ docker ps</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND                  CREATED             STATUS              PORTS                               NAMES</span></span>
<span class="line"><span>c4cd691d9f80        mysql:5.7           &quot;docker-entrypoint.s…&quot;   7 weeks ago         Up 12 days          0.0.0.0:3306-&gt;3306/tcp, 33060/tcp   mysql</span></span></code></pre></div><p>可以看到 mysql 正在被 id 为 c4cd691d9f80 的容器引用，我们需要首先通过 <code>docker stop c4cd691d9f80</code> 或者 <code>docker stop mysql</code>暂停这个容器。</p><p>然后查看 mysql 镜像的 id</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>➜  ~ docker images</span></span>
<span class="line"><span>REPOSITORY              TAG                 IMAGE ID            CREATED             SIZE</span></span>
<span class="line"><span>mysql                   5.7                 f6509bac4980        3 months ago        373MB</span></span></code></pre></div><p>通过 IMAGE ID 或者 REPOSITORY 名字即可删除</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker rmi f6509bac4980 #  或者 docker rmi mysql</span></span></code></pre></div><h3 id="_4、build-ship-and-run" tabindex="-1">4、Build Ship and Run <a class="header-anchor" href="#_4、build-ship-and-run" aria-label="Permalink to &quot;4、Build Ship and Run&quot;">​</a></h3><p>搜索 Docker 官网，会发现如下的字样：<strong>“Docker - Build, Ship, and Run Any App, Anywhere”</strong>。</p><ul><li><strong>Build（构建镜像）</strong>：镜像就像是集装箱包括文件以及运行环境等等资源。</li><li><strong>Ship（运输镜像）</strong>：主机和仓库间运输，这里的仓库就像是超级码头一样。</li><li><strong>Run （运行镜像）</strong>：运行的镜像就是一个容器，容器就是运行程序的地方。</li></ul><p>Docker 运行过程是会去仓库把镜像拉到本地，然后用一条命令把镜像运行起来变成容器。</p><p>Docker 也被称为码头工人或码头装卸工，这和 Docker 的中文翻译<strong>搬运工人</strong>如出一辙。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311171603190.png" alt="image.png"></p><hr><p>参考</p><ul><li><a href="https://javaguide.cn/tools/docker/docker-intro.html" target="_blank" rel="noreferrer">https://javaguide.cn/tools/docker/docker-intro.html</a></li><li><a href="https://www.pdai.tech/md/devops/docker/docker-01-docker-vm.html" target="_blank" rel="noreferrer">https://www.pdai.tech/md/devops/docker/docker-01-docker-vm.html</a></li><li><a href="https://www.pdai.tech/md/devops/docker/docker-03-basic2.html" target="_blank" rel="noreferrer">https://www.pdai.tech/md/devops/docker/docker-03-basic2.html</a></li><li><a href="https://bugstack.cn/md/road-map/docker.html" target="_blank" rel="noreferrer">https://bugstack.cn/md/road-map/docker.html</a></li><li><a href="https://bugstack.cn/md/road-map/linux.html" target="_blank" rel="noreferrer">https://bugstack.cn/md/road-map/linux.html</a></li></ul>`,63)])])}const k=a(t,[["render",r]]);export{h as __pageData,k as default};
